var img;
var squares = []

const grid = 12;
const count = 20;

function setup() {
	createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight));
	background("white");
	img = get();
	stroke("black");
	strokeWeight(9);
	strokeJoin(ROUND);
	strokeCap(PROJECT);
	pixelDensity(1);

	squares = []
	for (let i = 0; i < count; i++) {
		let xs = floor(random(1, 3));
		let ys = floor(random(1, 3));
		let x = floor(random(0, grid - xs));
		let y = floor(random(0, grid - ys));
		let c = floor(random(4));
		let a = floor(random(50, 100));
		squares.push({
			x: x,
			y: y,
			x_size: xs,
			y_size: ys,
			color: c,
			age: a
		})
	}
}

function draw() {
	push();
	translate(width / 2, height / 2);
	rotate(0.001 * sin(millis() / 10000));
	translate(-width / 2, -height / 2);
	image(img, 4, 4, width - 8, height - 8, 0, 0, width, height);
	pop();
	filter(POSTERIZE, 15);

	let cell = floor(0.95 * width / grid);
	let offset = floor(width - cell * grid);

	for (let i = 0; i < squares.length; i++) {
		if (squares[i].age <= 0) {
			let xs = floor(random(1, 3));
			let ys = floor(random(1, 3));
			let x = floor(random(0, grid - xs));
			let y = floor(random(0, grid - ys));
			let c = floor(random(4));
			let a = floor(random(50, 100));
			squares[i] = {
				x: x,
				y: y,
				x_size: xs,
				y_size: ys,
				color: c,
				age: a
			}
		}

		switch (squares[i].color) {
			case 0:
				fill("red");
				break;
			case 1:
				fill("blue");
				break;
			case 2:
				fill("yellow");
				break;
			case 3:
				fill("white");
				break;
		}

		if (random(1) < 0.001) {
			line(offset / 2, offset + squares[i].y * cell, offset + (grid - 0.5) * cell, offset + squares[i].y * cell);
			line(offset / 2, offset + (squares[i].y + squares[i].y_size) * cell, offset + (grid - 0.5) * cell, offset + (squares[i].y + squares[i].y_size) * cell);
			line(offset + squares[i].x * cell, offset / 2, offset + squares[i].x * cell, offset + (grid - 0.5) * cell);
			line(offset + (squares[i].x + squares[i].x_size) * cell, offset / 2, offset + (squares[i].x + squares[i].x_size) * cell, offset + (grid - 0.5) * cell);
		}

		rect(offset + squares[i].x * cell, offset + squares[i].y * cell, squares[i].x_size * cell, squares[i].y_size * cell);

		squares[i].age--;



	}

	img = get();

}

//disable default right mouse click
document.addEventListener("contextmenu", (event) => event.preventDefault(), "true")

//left click restarts, right click does an image capture
let lapse = 0; // mouse timer
function mousePressed() {
	if (millis() - lapse > 400) {
		lapse = millis();
		if (mouseButton === RIGHT) {
			save("img_" + year() + nf(month(), 2) + nf(day(), 2) + nf(hour(), 2) + nf(minute(), 2) + nf(second(), 2) + ".png");
		} else if (mouseButton === CENTER) {} else {
			setup(); // start a new image
		}
	}
	return (false)
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
